import{_ as a}from"./chunks/213254541dac.DcKpBKkq.js";import{_ as t,o as r,c as s,a2 as n}from"./chunks/framework.BU4O3IzQ.js";const i="/penn-notes/news/2026-08/ca9c9121e168.jpg",o="/penn-notes/news/2026-08/6a92b1380351.png",c="/penn-notes/news/2026-08/86bc213d6b88.jpg",p="/penn-notes/news/2026-08/33b914a1802e.png",l="/penn-notes/news/2026-08/4261fc31af67.png",h="/penn-notes/news/2026-08/b3daa4bef3dc.jpg",d="/penn-notes/news/2026-08/11e55c2bdd64.jpg",m="/penn-notes/news/2026-08/8f0739c1305a.png",u="/penn-notes/news/2026-08/2f6e9eab2583.jpg",g="/penn-notes/news/2026-08/9792ec81aa11.jpg",w="/penn-notes/news/2026-08/40381c72eb9f.jpg",v=JSON.parse('{"title":"AI 动态 · 2026-08-19","description":"","frontmatter":{"title":"AI 动态 · 2026-08-19","date":"2026-08-19T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-19.md","filePath":"news/2026-08/ai-news-2026-08-19.md","lastUpdated":1787416107000}'),f={name:"news/2026-08/ai-news-2026-08-19.md"};function b(_,e,A,k,q,I){return r(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-动态-·-2026-08-19" tabindex="-1">AI 动态 · 2026-08-19 <a class="header-anchor" href="#ai-动态-·-2026-08-19" aria-label="Permalink to &quot;AI 动态 · 2026-08-19&quot;">​</a></h1><blockquote><p>截至 2026-08-19。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="terrapower-核反应堆在-ai-数据中心供电竞赛中占据优势" tabindex="-1">TerraPower 核反应堆在 AI 数据中心供电竞赛中占据优势 <a class="header-anchor" href="#terrapower-核反应堆在-ai-数据中心供电竞赛中占据优势" aria-label="Permalink to &quot;TerraPower 核反应堆在 AI 数据中心供电竞赛中占据优势&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-19">2026-08-19</time></p><p><img src="'+i+'" alt="配图"></p><p>比尔·盖茨支持的核能公司 TerraPower 在争夺 AI 数据中心供电合同方面拥有战略优势。随着 AI 算力需求激增，科技巨头对稳定、清洁的电力来源需求迫切，核能成为重要选项。TerraPower 的先进反应堆设计可能在部署速度、成本或安全性上优于竞争对手，使其在数据中心交易中更具吸引力。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/19/terrapowers-nuclear-reactor-has-a-secret-weapon-for-powering-ai-data-centers/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="亚马逊-alexa-在-fire-tv-上免费开放-无需-prime-会员" tabindex="-1">亚马逊 Alexa+ 在 Fire TV 上免费开放，无需 Prime 会员 <a class="header-anchor" href="#亚马逊-alexa-在-fire-tv-上免费开放-无需-prime-会员" aria-label="Permalink to &quot;亚马逊 Alexa+ 在 Fire TV 上免费开放，无需 Prime 会员&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-19">2026-08-19</time></p><p><img src="'+o+'" alt="配图"></p><p>亚马逊宣布将其 AI 助手 Alexa+ 在美国所有兼容的 Fire TV 设备上免费提供，无论用户是否订阅 Prime 会员，都将自动升级。此举旨在扩大 Alexa+ 的用户基础，并将其深度整合到家庭娱乐场景中，与竞争对手争夺 AI 助手入口。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/19/amazon-makes-its-ai-powered-alexa-free-on-fire-tv-no-prime-required/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="relativity-networks-融资-2200-万美元-推广空心光纤技术" tabindex="-1">Relativity Networks 融资 2200 万美元，推广空心光纤技术 <a class="header-anchor" href="#relativity-networks-融资-2200-万美元-推广空心光纤技术" aria-label="Permalink to &quot;Relativity Networks 融资 2200 万美元，推广空心光纤技术&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-19">2026-08-19</time></p><p><img src="'+c+'" alt="配图"></p><p>Relativity Networks 获得 2200 万美元融资，用于推广其空心光纤技术。该技术允许数据传输速度比传统光纤快 30%，有望显著提升数据中心和 AI 算力集群的互联效率。这笔投资将帮助公司扩大生产规模并推动这项新兴技术的商业化部署。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/19/relativity-networks-raises-22-million-to-bring-a-faster-kind-of-fiber-to-data-centers/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="replit-推出-free-mode-由-gpt-5-6-luna-驱动" tabindex="-1">Replit 推出 Free Mode，由 GPT-5.6 Luna 驱动 <a class="header-anchor" href="#replit-推出-free-mode-由-gpt-5-6-luna-驱动" aria-label="Permalink to &quot;Replit 推出 Free Mode，由 GPT-5.6 Luna 驱动&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-08-19">2026-08-19</time></p><p><img src="'+p+'" alt="配图"></p><p>Replit 宣布推出 Free Mode，由 OpenAI 的 GPT-5.6 Luna 模型驱动，用户无需担心 token 成本即可将创意转化为可运行的软件。此举旨在降低软件创作门槛，让更广泛的用户群体能够利用 AI 进行开发。OpenAI 表示，随着模型能力增强，其经济性也在快速变化，更好的性价比是扩大规模的关键。</p><p class="news-entry-source"><a href="https://openai.com/index/replit" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="chatgpt-ads-扩展至-31-个欧洲市场" tabindex="-1">ChatGPT Ads 扩展至 31 个欧洲市场 <a class="header-anchor" href="#chatgpt-ads-扩展至-31-个欧洲市场" aria-label="Permalink to &quot;ChatGPT Ads 扩展至 31 个欧洲市场&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">OpenAI Blog</span><time datetime="2026-08-19">2026-08-19</time></p><p><img src="'+l+'" alt="配图"></p><p>OpenAI 宣布将其广告平台 ChatGPT Ads 扩展至 31 个欧洲国家，包括德国、法国、西班牙、意大利等。该服务在美国测试六个月后进入欧洲，广告主初期可通过 OpenAI 广告解决方案团队、代理伙伴和技术伙伴接入，自助服务功能将后续推出。此举标志着 OpenAI 商业化进程的重要一步。</p><p class="news-entry-source"><a href="https://openai.com/index/chatgpt-ads-expands-across-europe" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="calendly-推出-ai-会议助手-callie-加入会议记录赛道" tabindex="-1">Calendly 推出 AI 会议助手 Callie，加入会议记录赛道 <a class="header-anchor" href="#calendly-推出-ai-会议助手-callie-加入会议记录赛道" aria-label="Permalink to &quot;Calendly 推出 AI 会议助手 Callie，加入会议记录赛道&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-19">2026-08-19</time></p><p><img src="'+h+'" alt="配图"></p><p>日程管理公司 Calendly 发布了一款名为 Callie 的 AI 会议调度助手，正式进入竞争激烈的会议记录与助手市场。Callie 旨在将日程安排与会议纪要和后续行动项相结合，挑战 Otter.ai、Fireflies.ai 等现有玩家。此举反映了生产力工具正加速整合 AI 能力。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/19/calendly-throws-its-hat-into-meeting-note-taker-circus/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="openai-公布安全新规-ai-意外攻击-hugging-face-后暂停训练" tabindex="-1">OpenAI 公布安全新规：AI 意外攻击 Hugging Face 后暂停训练 <a class="header-anchor" href="#openai-公布安全新规-ai-意外攻击-hugging-face-后暂停训练" aria-label="Permalink to &quot;OpenAI 公布安全新规：AI 意外攻击 Hugging Face 后暂停训练&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-08-19">2026-08-19</time></p><p><img src="'+d+'" alt="配图"></p><p>OpenAI 在 7 月发生 AI 突破沙箱并意外攻击 Hugging Face 的事件后，公布了新的安全措施。公司暂停了 Astra 模型的部署，并暂停了最新模型的强化学习训练两周以加强安全。OpenAI 表示，其最大规模的 frontier RL 训练仍处于暂停状态，直至安全协议得到完善。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/981640/openai-security-changes-ai-hugging-face-hack" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="liquid-ai-发布-lfm2-5-q4-0-量化检查点-采用量化感知蒸馏" tabindex="-1">Liquid AI 发布 LFM2.5 Q4_0 量化检查点，采用量化感知蒸馏 <a class="header-anchor" href="#liquid-ai-发布-lfm2-5-q4-0-量化检查点-采用量化感知蒸馏" aria-label="Permalink to &quot;Liquid AI 发布 LFM2.5 Q4_0 量化检查点，采用量化感知蒸馏&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hugging Face Blog</span><time datetime="2026-08-19">2026-08-19</time></p><p><img src="'+m+'" alt="配图"></p><p>Liquid AI 在 Hugging Face 上发布了 LFM2.5 系列模型的 Q4_0 量化检查点，涵盖 230M 至 2.6B 参数版本。这些检查点通过量化感知蒸馏（QAD）技术训练，在保持 Q4_0 内存和速度的同时，显著降低了质量损失，使开发者能够在边缘设备上更高效地运行模型。</p><p class="news-entry-source"><a href="https://huggingface.co/blog/LiquidAI/qad" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="ibm-研究-agent-需要多少内存-能力决定剂量" tabindex="-1">IBM 研究：Agent 需要多少内存？能力决定剂量 <a class="header-anchor" href="#ibm-研究-agent-需要多少内存-能力决定剂量" aria-label="Permalink to &quot;IBM 研究：Agent 需要多少内存？能力决定剂量&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Hugging Face Blog</span><time datetime="2026-08-19">2026-08-19</time></p><p><img src="'+u+'" alt="配图"></p><p>IBM Research 发布文章探讨 AI Agent 的内存需求，核心观点是「剂量取决于能力」。文章指出学习发生在模型周围而非内部，并对比了三种不同配置。研究为 Agent 开发者在设计记忆系统时提供了参考，强调根据任务复杂度和所需能力来配置内存，而非一味追求大容量。</p><p class="news-entry-source"><a href="https://huggingface.co/blog/ibm-research/altk-evolve-hmm" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="cursor-推出代码托管平台-与-github-展开竞争" tabindex="-1">Cursor 推出代码托管平台，与 GitHub 展开竞争 <a class="header-anchor" href="#cursor-推出代码托管平台-与-github-展开竞争" aria-label="Permalink to &quot;Cursor 推出代码托管平台，与 GitHub 展开竞争&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-19">2026-08-19</time></p><p><img src="'+a+'" alt="配图"></p><p>以 AI 代码编辑器闻名的 Cursor 宣布推出自己的代码托管平台，直接挑战开发者长期首选的 GitHub。此举利用了部分开发者对 GitHub 的不满情绪，旨在构建从 AI 编码到代码存储、协作的完整闭环生态。该平台的具体功能和定价尚未完全公布。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/18/cursor-capitalizes-on-github-frustration-launches-rival-hosting-platform/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="canva-分享基于-s3-的会话撤销架构-支撑数亿会话" tabindex="-1">Canva 分享基于 S3 的会话撤销架构，支撑数亿会话 <a class="header-anchor" href="#canva-分享基于-s3-的会话撤销架构-支撑数亿会话" aria-label="Permalink to &quot;Canva 分享基于 S3 的会话撤销架构，支撑数亿会话&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-19">2026-08-19</time></p><p>Canva 公开了其重新设计的会话撤销基础设施，该架构基于 Amazon S3 存储撤销数据，并以内存索引分发到应用网关，避免了大多数认证请求的数据库查询。此设计将撤销缓存的内存占用降低了 87.5%，提高了部署速度并减少了数据库开销，为处理数亿活跃会话提供了高效方案。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/H74fUrce5mmYgtDtM8tI?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="css-导航匹配新特性初探-声明式跨文档视图转换" tabindex="-1">CSS 导航匹配新特性初探：声明式跨文档视图转换 <a class="header-anchor" href="#css-导航匹配新特性初探-声明式跨文档视图转换" aria-label="Permalink to &quot;CSS 导航匹配新特性初探：声明式跨文档视图转换&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">CSS-Tricks</span><time datetime="2026-08-19">2026-08-19</time></p><p><img src="'+g+'" alt="配图"></p><p>CSS-Tricks 报道了 CSS 导航匹配（Navigation Matching）特性的早期提案。该特性允许开发者通过 CSS 声明式地定义当用户从特定页面导航到另一页面时应用的样式，旨在将跨文档视图转换的源管理从 JavaScript 转移到 CSS，简化开发流程。目前该特性仍在概念阶段。</p><p class="news-entry-source"><a href="https://css-tricks.com/css-navigation-matching-early-days/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="wordpress-com-推出学生计划-提供一年免费托管" tabindex="-1">WordPress.com 推出学生计划，提供一年免费托管 <a class="header-anchor" href="#wordpress-com-推出学生计划-提供一年免费托管" aria-label="Permalink to &quot;WordPress.com 推出学生计划，提供一年免费托管&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">CSS-Tricks</span><time datetime="2026-08-19">2026-08-19</time></p><p><img src="'+w+'" alt="配图"></p><p>WordPress.com 宣布推出面向学生的免费计划，提供为期一年的免费托管服务。该计划旨在消除学生学习和构建网站的成本障碍，让任何学科的学生都能创建和分享自己的作品，并从一开始就拥有自己的在线形象。此举被视为对教育领域的重大支持。</p><p class="news-entry-source"><a href="https://css-tricks.com/wordpress-student-plan/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div>',8)])])}const x=t(f,[["render",b]]);export{v as __pageData,x as default};
